SECOND_READ_REFUSALS: Final[dict[str, Callable[..., None]]] = {
    "a refused file": refusing_coded("SQLITE_IOERR"),
    "a busy store": refusing(StoreBusy),
    "a busy writer": refusing(WriterBusy),
    "another refusal": refusing(DraftFrozen),
}


