    post_read = ("state_of_review", "draft_for_save", THE_PAGE_S_READ_OF_THE_POST[press], refused)
    with here(open_settings(tmp_path)) as browser:
        beside = a_press_beside_a_save(browser, monkeypatch, press, words=words)
