        draft_id, page, first, other = two_rows(browser, monkeypatch)
        posted = page_post(page, "save", tick=[first], typed=typed_on(other))

        def closing(*_: object, **__: object) -> NotSaved:
            discarded(browser, draft_id)
            return NotSaved("failed")

